/* =========================================================
   DATA — EXERCISES
   Jede Kategorie liefert eine Funktion getBank(), die ein
   Array von Fragen zurückgibt:
   { prompt, options:[...], correct:[idx,...], explain }
   `correct` kann mehrere Indizes enthalten -> Bonuspunkt-Logik.
   ========================================================= */

