  function bankHaeufigeFehler() {
    return Core.shuffle(HAEUFIGE_FEHLER).map(([wrong, correct, explain]) => {
      const opts = Core.shuffle([correct, wrong]);
      return {
        prompt: `Welche Form ist richtig?`,
        options: opts,
        correct: [opts.indexOf(correct)],
        explain,
      };
    });
  }

