  function bankNebensatz() {
    return Core.shuffle(NEBENSATZ).map(([sentence, correct, wrong, explain]) => {
      const opts = Core.shuffle([correct, wrong]);
      return {
        prompt: sentence,
        options: opts,
        correct: [opts.indexOf(correct)],
        explain,
      };
    });
  }

